+    let mut req = generate_req(25, SamplingParams::default());
+    let RequestKind::Generate(g) = &mut req.kind else {
+        unreachable!()
+    };
+    g.top_logprobs_num = limits.vocab_size as i64;
+    assert!(
+        validate(&mut req, &limits).is_ok(),
+        "k == vocab_size must be admitted"
+    );
